setup.snippet:
// The kit's pieces are 3-D: EngineConfig(graphics3D: Graphics3D(),
// physics3D: Physics3D()).
WorldBuilderKit.registerSystems(engine.world);
// After each level is loaded, before the game runs: its terrains and
// tile libraries read, so they are solid from the first step.
await SceneLoader.loadAsset(engine.world, level);
await WorldBuilderKit.ready(engine.world);
